// Copies the baked campus map into a module the Map screen can import.
//
// The drawing itself is generated by the design's own tool
// (docs/design/tools/bake-map.mjs), which bakes OpenStreetMap data into a few SVG paths so the
// map works offline with no tiles and no network. This script only re-publishes that object as a
// typed module, so the web app reads the same geometry the approved mockups show.
//
//   node scripts/gen-map-data.mjs
//
// Map data © OpenStreetMap contributors, Open Database Licence 1.0 (see docs/design/CREDITS.md).

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const SOURCE = join(here, '..', '..', 'docs', 'design', 'prototype', 'assets', 'campus-map.js');
const OUT = join(here, '..', 'src', 'components', 'map', 'campusMapData.ts');

const text = readFileSync(SOURCE, 'utf8');
const start = text.indexOf('window.SABI_MAP = ');
if (start === -1) throw new Error('campus-map.js has no SABI_MAP object');
const json = text
  .slice(start + 'window.SABI_MAP = '.length)
  .trim()
  .replace(/;\s*$/, '');
const map = JSON.parse(json);

const header = `// Generated by web/scripts/gen-map-data.mjs — do not edit by hand.
// Source: docs/design/prototype/assets/campus-map.js (baked by docs/design/tools/bake-map.mjs).
//
// Map data © OpenStreetMap contributors, Open Database Licence 1.0. Nothing here is routing.
// Drawing units are half a metre. \`bbox\` is [south, west, north, east]; x runs west to east and
// y runs north to south from the top left corner, exactly as the bake tool projects it.
`;

const types = `export interface CampusMapData {
  attribution: string;
  licence: string;
  unit: number;
  /** [width, height] in drawing units. */
  size: [number, number];
  /** [south, west, north, east] in degrees. */
  bbox: [number, number, number, number];
  layers: Record<'grass' | 'wood' | 'water' | 'pitch' | 'lanes' | 'roads' | 'buildings', string>;
  /** The places the bake tool named. Pins on screen come from the offline cache instead. */
  places: { id: string; name: string; cat: string; x: number; y: number; osm: string }[];
}
`;

mkdirSync(dirname(OUT), { recursive: true });
const body = JSON.stringify(map, null, 2).replace(/"([^"\\]+)":/g, '$1:');
writeFileSync(OUT, `${header}\n${types}\nexport const CAMPUS_MAP: CampusMapData = ${body};\n`);
console.log(`wrote ${OUT} (${JSON.stringify(map).length} bytes of map data)`);
